--
-- Name: gl_assert_entry_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gl_assert_entry_balanced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_entry_id bigint;
    v_status   text;
    v_diff     numeric;
BEGIN
    IF TG_TABLE_NAME = 'journal_entries' THEN
        v_entry_id := NEW.id;
        v_status   := NEW.status;
    ELSE
        v_entry_id := COALESCE(NEW.entry_id, OLD.entry_id);
        SELECT status INTO v_status FROM journal_entries WHERE id = v_entry_id;
    END IF;

    IF v_status = 'POSTED' THEN
        SELECT COALESCE(SUM(debit_base), 0) - COALESCE(SUM(credit_base), 0)
          INTO v_diff FROM journal_lines WHERE entry_id = v_entry_id;
        IF ABS(COALESCE(v_diff, 0)) > 0.005 THEN
            RAISE EXCEPTION 'Journal entry % is unbalanced by % (functional currency)', v_entry_id, v_diff;
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: gl_block_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gl_block_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.status = 'POSTED' THEN
    RAISE EXCEPTION 'Posted ledger entries are immutable (id=%); post a reversal instead', OLD.id;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'POSTED'
     AND (NEW.entry_hash IS DISTINCT FROM OLD.entry_hash
          OR NEW.entry_date <> OLD.entry_date
          OR NEW.entity_id  <> OLD.entity_id) THEN
    -- allow ONLY the status flip POSTED->REVERSED + reversed_by linkage
    IF NOT (NEW.status = 'REVERSED' AND OLD.status = 'POSTED') THEN
      RAISE EXCEPTION 'Posted ledger entry % is immutable', OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: org_set_path(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_set_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p_path text; p_depth int;
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.path := NEW.id::text; NEW.depth := 0;
    ELSE
        SELECT path, depth INTO p_path, p_depth FROM org_units WHERE id = NEW.parent_id;
        NEW.path := p_path || '.' || NEW.id; NEW.depth := p_depth + 1;
    END IF;
    RETURN NEW;
END; $$;


--
-- Name: owning_entity_id(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owning_entity_id(p_unit bigint) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE up AS (
    SELECT id, parent_id, is_legal_entity FROM org_units WHERE id = p_unit
    UNION ALL
    SELECT o.id, o.parent_id, o.is_legal_entity FROM org_units o JOIN up ON o.id = up.parent_id
  ) SELECT id FROM up WHERE is_legal_entity ORDER BY id LIMIT 1;
$$;


--
-- Name: user_allowed_locations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_allowed_locations(p_user integer) RETURNS TABLE(org_unit_id bigint, access text)
    LANGUAGE sql STABLE
    AS $$
  SELECT d.id AS org_unit_id,
         (ARRAY_AGG(a.access ORDER BY
            CASE a.access WHEN 'ADMIN' THEN 0 WHEN 'POST' THEN 1
                          WHEN 'EDIT' THEN 2 ELSE 3 END))[1] AS access
  FROM user_org_access a
  JOIN org_units g ON g.id = a.org_unit_id
  JOIN org_units d ON d.path LIKE g.path || '%'
  WHERE a.user_id = p_user
  GROUP BY d.id;
$$;


