    invoice_type character varying(20) DEFAULT 'CLIENT'::character varying NOT NULL,
    bill_to_region_id integer,
    tenant_id integer NOT NULL,
    CONSTRAINT invoices_bill_to_not_self_check CHECK (((bill_to_region_id IS NULL) OR (bill_to_region_id <> region_id))),
    CONSTRAINT invoices_ic_zero_rated_check CHECK ((((invoice_type)::text <> 'INTER_COMPANY'::text) OR ((tax_amount = (0)::numeric) AND (tax_lines_json = '[]'::jsonb)))),
    CONSTRAINT invoices_invoice_status_check CHECK (((invoice_status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('GENERATED'::character varying)::text, ('SENT'::character varying)::text, ('PARTIALLY_PAID'::character varying)::text, ('PAID'::character varying)::text, ('OVERDUE'::character varying)::text, ('CANCELLED'::character varying)::text]))),
    CONSTRAINT invoices_invoice_type_check CHECK (((invoice_type)::text = ANY (ARRAY[('CLIENT'::character varying)::text, ('INTER_COMPANY'::character varying)::text]))),
    CONSTRAINT invoices_quickbooks_sync_status_check CHECK (((quickbooks_sync_status)::text = ANY (ARRAY[('NOT_SYNCED'::character varying)::text, ('SYNCED'::character varying)::text, ('FAILED'::character varying)::text]))),
    CONSTRAINT invoices_type_shape_check CHECK (((((invoice_type)::text = 'CLIENT'::text) AND (client_id IS NOT NULL) AND (placement_id IS NOT NULL) AND (bill_to_region_id IS NULL)) OR (((invoice_type)::text = 'INTER_COMPANY'::text) AND (bill_to_region_id IS NOT NULL) AND (client_id IS NULL) AND (placement_id IS NULL))))
);

